import {mountIncidentDetective} from './incident-detective-ui.mjs';
import {packetMatchesSelection} from './intelligence-packet.mjs';
const root=document.querySelector('#intelligence-app');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let overview=null,discovery=null,packet=null,activeCase=null,notice='',scanning=false,packetRequest=0,viewActive=true;
window.addEventListener('pagehide',()=>{viewActive=false;packetRequest++;packet=null;});

async function api(path,body,timeoutMs=30000){
 const response=await fetch('/api/'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(timeoutMs)});
 const value=await response.json();if(!response.ok)throw Error(value.error||'The request could not be completed.');return value;
}
const badge=(status,text)=>`<span class="badge ${esc(status)}">${esc(text)}</span>`;
const amount=minor=>(minor/100).toFixed(2);
const group=(label,items)=>`<details class="result-group"><summary><strong>${esc(label)}</strong><span>${items.length}</span></summary>${items.length?`<ul>${items.map(item=>`<li><b>${esc(item.caseId)}</b><small>${esc(item.reason)}</small></li>`).join('')}</ul>`:'<p>No cases in this group.</p>'}</details>`;

function render(){
 if(!overview)return;
 const {incident,rehearsal,policy,caseOptions}=overview;
 root.innerHTML=`<div class="notice" role="status">${esc(notice)}</div><div class="lab-grid"><section class="lab-card incident ${incident.active?'active':''}"><div class="card-head"><span class="eyebrow">01 / POSSIBLE INCIDENT</span>${badge(incident.active?'hold':'clear',incident.active?'Automatic grants paused':'No active cluster')}</div><h2>${incident.active?`${incident.count} purchases. One course. One window.`:'Is this more than one case?'}</h2><p>${esc(incident.reason)}</p>${incident.active?`<div class="incident-window"><strong>30-minute cluster</strong><span>${esc(incident.courseId)} · ${esc(incident.caseIds.join(', '))}</span></div><p class="fine">This is a pattern, not a proven shared root cause. Individual payment and entitlement checks still apply.</p>`:'<p class="fine">Three or more completed sandbox payments with missing access for the same course trigger this signal.</p>'}</section><section class="lab-card discovery"><div class="card-head"><span class="eyebrow">02 / PAYPAL DISCOVERY</span>${badge(discovery?.state==='connected'?'clear':'neutral',discovery?.state==='connected'?'Scan complete':'Read-only scan')}</div><h2>Find purchases outside the queue.</h2><p>Scan the last 24 hours of PayPal sandbox reporting and compare transaction IDs with saved cases. Reporting can lag by hours.</p><button type="button" id="scan" class="button primary" ${scanning?'disabled':''}> Scan PayPal reporting</button><div id="discovery-result" class="discovery-result">${discovery?`<p class="fine">${esc(discovery.detail)}</p>${discovery.state==='connected'?`<div class="metric-row"><div><strong>${discovery.items.length}</strong><span>reporting rows</span></div><div><strong>${discovery.items.filter(x=>!x.caseId).length}</strong><span>need merchant match</span></div></div>${discovery.truncated?'<p class="fine">More pages are available. This prototype displays the first 100 rows only.</p>':''}<div class="transaction-list">${discovery.items.slice(0,20).map(item=>`<div><strong>${esc(item.transactionId)}</strong><span>${esc(item.amount||'—')} ${esc(item.currency||'')} · ${esc(item.reportedStatus)} · ${esc(item.caseId||'Learner/course match needed')}</span></div>`).join('')||'<p>No reported transactions in this window.</p>'}</div>`:''}`:'<p class="fine">No scan has been run in this session. This does not create cases or change access.</p>'}</div></section><section class="lab-card policy"><div class="card-head"><span class="eyebrow">03 / POLICY REHEARSAL</span>${badge('neutral','No writes')}</div><h2>See what autopilot would do.</h2><p>Try a purchase limit and daily cap against saved cases. Current model reviews are required for a “would recover” result.</p><form id="policy-form"><label>Maximum purchase (USD)<input name="amount" type="number" min="0.01" max="500" step="0.01" value="${esc(amount(policy.maxAmountCents))}" required></label><label>Daily recovery cap<input name="limit" type="number" min="1" max="10" step="1" value="${esc(policy.dailyLimit)}" required></label><button type="submit" class="button primary">Rehearse policy</button></form><div class="metric-row">${[['wouldRecover','Would recover'],['needsReview','Need review'],['held','Held'],['alreadyAccess','Already active']].map(([key,label])=>`<div><strong>${rehearsal.counts[key]}</strong><span>${label}</span></div>`).join('')}</div>${group('Cases fitting the policy',rehearsal.wouldRecover)}${group('Needs a model review',rehearsal.needsReview)}${group('Held safely',rehearsal.held)}<p class="fine">${esc(rehearsal.definition)} ${incident.active?'Incident mode pauses automatic grants even if a case fits.':''}</p></section><section class="lab-card packet"><div class="card-head"><span class="eyebrow">04 / EVIDENCE PACKET</span>${badge('neutral','Merchant review')}</div><h2>Put the case story in one place.</h2><p>Prepare a timeline of payment checks, approval, verification, and customer contact. The packet omits message text and email addresses.</p><label>Case<select id="packet-case"><option value="">Choose a case</option>${caseOptions.map(item=>`<option value="${esc(item.id)}" ${item.id===activeCase?'selected':''}>${esc(item.id)} · ${esc(item.phase)} · ${esc(item.source)}</option>`).join('')}</select></label><button type="button" id="prepare-packet" class="button primary" ${activeCase?'':'disabled'}>Prepare packet</button><div id="packet-result">${packet?`<div class="packet-summary"><div><strong>${esc(packet.payment.status)}</strong><span>Payment status</span></div><div><strong>${packet.purchaseChecks.filter(x=>x.passed).length}/${packet.purchaseChecks.length}</strong><span>Purchase checks</span></div><div><strong>${packet.repair.accessWrites}</strong><span>Access writes</span></div><div><strong>${packet.verification.current?'Current':'Pending'}</strong><span>Verification</span></div></div><p class="fine">${esc(packet.purpose)} · Generated ${esc(new Date(packet.generatedAt).toLocaleString())}</p><button type="button" id="download-packet" class="button secondary">Download JSON packet</button>`:'<p class="fine">Nothing is sent to PayPal. Select a case to prepare an internal packet.</p>'}</div></section></div>`;
 mountIncidentDetective(root,incident,api);
 root.querySelector('#scan').onclick=async()=>{if(scanning)return;scanning=true;notice='Scanning PayPal reporting without changing a case…';render();try{discovery=await api('intelligence/discover',undefined,45000);notice=discovery.state==='connected'?'Scan complete. Unlinked rows still need a merchant match.':discovery.detail;}catch(error){notice=error.message;}finally{scanning=false;render();}};
 root.querySelector('#policy-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,max=Math.round(Number(form.elements.namedItem('amount').value)*100),limit=Number(form.elements.namedItem('limit').value);try{overview=await api(`intelligence?maxAmountCents=${max}&dailyLimit=${limit}`);notice='Policy rehearsed. No access changed.';}catch(error){notice=error.message;}render();};
 root.querySelector('#packet-case').onchange=event=>{activeCase=event.target.value;packet=null;packetRequest++;render();};
 root.querySelector('#prepare-packet').onclick=async()=>{if(!activeCase)return;const caseId=activeCase,request=++packetRequest;packet=null;notice='Preparing the selected case packet…';render();try{const result=await api('intelligence/packet?caseId='+encodeURIComponent(caseId));if(!viewActive||request!==packetRequest||activeCase!==caseId)return;if(!packetMatchesSelection({viewActive,activeCase,request,latestRequest:packetRequest,packet:result}))throw Error('The packet did not match the selected case. Refresh and try again.');packet=result;notice='Case packet prepared for merchant review.';}catch(error){if(!viewActive||request!==packetRequest||activeCase!==caseId)return;notice=error.message;}render();};
 root.querySelector('#download-packet')?.addEventListener('click',()=>{if(!packetMatchesSelection({viewActive,activeCase,request:packetRequest,latestRequest:packetRequest,packet}))return;const file=new Blob([JSON.stringify(packet,null,2)],{type:'application/json'}),url=URL.createObjectURL(file),link=document.createElement('a');link.href=url;link.download=packet.caseId+'-merchant-packet.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
}

async function load(){
 if(window.COURSELATCH_RUNTIME?.backend!==true){root.innerHTML='<section class="lab-card"><h2>Connect the backend first.</h2><p>This intelligence desk needs a server-backed merchant workspace.</p><a href="focus.html">Return to the recovery desk</a></section>';return;}
 try{await api('state');overview=await api('intelligence');render();}
 catch(error){if(window.COURSELATCH_RUNTIME?.authRequired){root.innerHTML='<section class="lab-card"><h2>Merchant sign-in required.</h2><p>Open your verified merchant account to use this desk.</p><a href="account.html">Open merchant account →</a></section>';return;}root.innerHTML=`<section class="lab-card unlock"><span class="eyebrow">MERCHANT ACCESS</span><h2>Unlock the intelligence desk.</h2><p>Use the demo operator key configured on the server. It stays in your browser session.</p><form id="unlock-form"><label>Operator key<input name="key" type="password" required autocomplete="off"></label><button class="button primary">Unlock</button></form><p id="unlock-error" role="alert">${esc(error.message)}</p></section>`;root.querySelector('#unlock-form').onsubmit=async event=>{event.preventDefault();const input=event.currentTarget.elements.namedItem('key');try{await api('operator',{key:input.value});input.value='';overview=await api('intelligence');render();}catch(e){root.querySelector('#unlock-error').textContent=e.message;}};}
}
await load();
